import 'dart:convert';import 'package:flutter/material.dart';import 'package:intl/intl.dart';import '../../../core/data/astro_repository.dart';import '../../../core/data/local_database.dart';import '../../../core/models/reading.dart';import '../../../core/models/zodiac_sign.dart';import '../../../shared/widgets/app_components.dart';
class ArchiveScreen extends StatefulWidget{const ArchiveScreen({super.key});@override State<ArchiveScreen> createState()=>_ArchiveScreenState();}
class _ArchiveScreenState extends State<ArchiveScreen>{List<HoroscopeReading> rows=[];String sign='aries';DateTime month=DateTime(2026,11);@override void initState(){super.initState();_load();}
Future<void> _load()async{sign=await AstroRepository.instance.selectedSign();final db=await LocalDatabase.instance.database;final cached=await db.query('content_cache');final found=<HoroscopeReading>[];for(final item in cached){try{final doc=jsonDecode(item['payload'] as String);if(doc is Map&&doc['readings'] is List){for(final raw in doc['readings']){found.add(HoroscopeReading.fromJson(Map<String,dynamic>.from(raw)));}}}catch(_){}}if(mounted)setState(()=>rows=found);}
@override Widget build(BuildContext context){final available=rows.where((r)=>r.signId==sign&&r.periodType=='daily').toList()..sort((a,b)=>b.periodStart.compareTo(a.periodStart));final monthKey=DateFormat('yyyy-MM').format(month);return Scaffold(appBar:AppBar(title:const Text('Reading archive')),body:ListView(padding:const EdgeInsets.all(20),children:[const PageHeader('Your reading archive',subtitle:'Only published, cached dates are shown.'),Row(children:[IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month-1)),icon:const Icon(Icons.chevron_left)),Expanded(child:Center(child:Text(monthKey,style:Theme.of(context).textTheme.titleLarge))),IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month+1)),icon:const Icon(Icons.chevron_right))]),if(available.isEmpty)const InfoCard('No historical reading packs are cached yet. When a dated pack is published and downloaded, it will appear here.'),for(final r in available.where((r)=>r.periodStart.startsWith(monthKey)))Card(child:ListTile(title:Text(r.title),subtitle:Text(r.periodStart+' · '+(zodiacById[r.signId]?.name??r.signId)),onTap:()=>showDialog(context:context,builder:(_)=>AlertDialog(title:Text(r.title),content:Text(r.body))))),const DisclaimerCard()]));}
}
